public static class ResilientHttpClientExtensions
{
    /// <summary>
    /// Register a named, typed <see cref="HttpClient"/> through
    /// <see cref="IHttpClientFactory"/> with a retry + circuit-breaker +
    /// timeout <c>AddResilienceHandler</c> pipeline. Every dependency client
    /// this service generates (Consul remote-config/discovery, third-party
    /// REST integration providers, the ArcGIS client, inter-service/extern
    /// typed clients, and the @retry endpoint decorator's own outbound call)
    /// calls this instead of constructing an <see cref="HttpClient"/> directly.
    /// </summary>
    /// <param name="onRetryAttempt">
    /// Optional callback invoked on every Polly retry attempt -- some
    /// callers pass a closure incrementing
    /// <c>ResilienceMetrics.RetryAttempts</c> when the shared `resilience`
    /// feature applies to the generating service; every other caller omits
    /// it (a no-op by default).
    /// </param>
    /// <param name="onCircuitBreakerStateChanged">
    /// Optional callback invoked with the circuit breaker's new state
    /// ("Open"/"Closed"/"HalfOpen") on every transition -- some
    /// callers pass a closure incrementing
    /// <c>ResilienceMetrics.CircuitBreakerTransitions</c>; every other
    /// caller omits it.
    /// </param>
    public static void AddResilientHttpClient(
        this IServiceCollection services,
        string name,
        Action<HttpClient> configureClient,
        ResilientClientOptions? options = null,
        Action? onRetryAttempt = null,
        Action<string>? onCircuitBreakerStateChanged = null
    )
    {
        var opts = options ?? ResilientClientOptions.Default;
        services
            .AddHttpClient(name, configureClient)
            .AddResilienceHandler(
                $"{name}-pipeline",
                builder =>
                {
                    builder.AddRetry(
                        new HttpRetryStrategyOptions
                        {
                            MaxRetryAttempts = opts.MaxRetryAttempts,
                            BackoffType = DelayBackoffType.Exponential,
                            UseJitter = true,
                            Delay = opts.RetryInitialDelay,
                            OnRetry = args =>
