                                onRetryAttempt?.Invoke();
                                return default;
                            },
                        }
                    );
                    builder.AddCircuitBreaker(
                        new HttpCircuitBreakerStrategyOptions
                        {
                            FailureRatio = opts.CircuitBreakerFailureRatio,
                            SamplingDuration = opts.CircuitBreakerSamplingDuration,
                            MinimumThroughput = opts.CircuitBreakerMinimumThroughput,
                            BreakDuration = opts.CircuitBreakerBreakDuration,
                            OnOpened = args =>
                            {
                                onCircuitBreakerStateChanged?.Invoke("Open");
                                return default;
                            },
                            OnClosed = args =>
                            {
                                onCircuitBreakerStateChanged?.Invoke("Closed");
                                return default;
                            },
                            OnHalfOpened = args =>
                            {
                                onCircuitBreakerStateChanged?.Invoke("HalfOpen");
                                return default;
                            },
                        }
                    );
                    builder.AddTimeout(opts.Timeout);
